sys_security_acl.script:
if (gs.hasRole('x_fresh_guard_360.admin') || gs.hasRole('x_fresh_guard_360.food_safety_officer')) answer = true;
else if (gs.hasRole('x_fresh_guard_360.store_manager')) answer = (current.u_store.u_store_manager == gs.getUserID());
else if (gs.hasRole('x_fresh_guard_360.supplier')) answer = (current.u_product.u_supplier.u_email == gs.getUser().getEmail());
else answer = false;
